import fs from 'fs'
import path from 'path'
import { FieldValue } from 'firebase-admin/firestore'
import { getStorage } from 'firebase-admin/storage'
import { db, getStorageBucketName } from '../../firebase'
import type { PipelinePhase } from './types'

const bucket = () => getStorage().bucket(getStorageBucketName())

const pipelinePath = (sessionId: string, file: string) =>
  `projects/${sessionId}/pipeline/${file}`

function getPublicUrl(bucketName: string, filePath: string): string {
  return `https://storage.googleapis.com/${bucketName}/${filePath}`
}

export async function pipelineFileExists(
  sessionId: string,
  file: string
): Promise<boolean> {
  try {
    const [exists] = await bucket().file(pipelinePath(sessionId, file)).exists()
    return exists
  } catch {
    return false
  }
}

export async function uploadPipelineJson(
  sessionId: string,
  file: string,
  data: unknown
): Promise<string> {
  const filePath = pipelinePath(sessionId, file)
  const fileRef = bucket().file(filePath)
  await fileRef.save(JSON.stringify(data), { contentType: 'application/json' })
  await fileRef.makePublic()
  return getPublicUrl(fileRef.bucket.name, filePath)
}

export async function downloadPipelineJson<T>(
  sessionId: string,
  file: string
): Promise<T> {
  const filePath = pipelinePath(sessionId, file)
  try {
    const [buffer] = await bucket().file(filePath).download()
    return JSON.parse(buffer.toString()) as T
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err)
    throw new Error(`Pipeline file not found or unreadable: ${filePath} (${message})`)
  }
}

export async function uploadPipelineFile(
  sessionId: string,
  storagePath: string,
  localPath: string,
  contentType: string
): Promise<string> {
  const filePath = pipelinePath(sessionId, storagePath)
  const fileRef = bucket().file(filePath)
  await fileRef.save(fs.readFileSync(localPath), { contentType })
  await fileRef.makePublic()
  return getPublicUrl(fileRef.bucket.name, filePath)
}

export async function updatePipelinePhase(
  sessionId: string,
  phase: PipelinePhase,
  extra?: Record<string, unknown>
): Promise<void> {
  await db.collection('sessions').doc(sessionId).set(
    {
      pipelinePhase: phase,
      pipelineUpdatedAt: FieldValue.serverTimestamp(),
      ...extra,
    },
    { merge: true }
  )
}
